<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="5"><title>Payment status</title><style>body{font-family:ui-sans-serif,system-ui;background:#f6f7f4;color:#183027}.card{max-width:32rem;margin:12vh auto;background:#fff;padding:2rem;border-radius:1rem}.state{font-size:2rem;font-weight:750}</style></head><body><main class="card"><h1>Payment status</h1><p class="state">{{ str_replace('_',' ',ucfirst($attempt->state->value)) }}</p><p>We confirm payments from Mercado Pago directly. This page refreshes while confirmation is pending; the browser return itself never records money.</p>@if($attempt->state->value === 'approved')<p>Your payment has been confirmed. You may close this page.</p>@elseif(in_array($attempt->state->value,['rejected','cancelled','expired','failed','mismatched']))<p>No successful payment was recorded. Contact the property or return to your original secure link.</p>@endif</main></body></html>
